import random
def experiment(inputs):
    trials = inputs.get('trials', 100)
    seeds = inputs.get('seeds', [1, 2, 3])
    results = {'structured_variance': [], 'noise_variance': []}
    for seed in seeds:
        random.seed(seed)
        noise_trace = [random.gauss(0.5, 0.2) for _ in range(50)]
        structured_trace = [0.5 + 0.05 * i for i in range(50)]
        results['noise_variance'].append(sum(noise_trace)/50)
        results['structured_variance'].append(sum(structured_trace)/50)
    return {'measurements': {'preference_convergence_rate': [sum(results['structured_variance'])/len(results['structured_variance'])]}}
